// Header-icon probe. c1 found no row that was 40 percent saturated green.
// This version records the top rows and hashes the icon above the strongest
// green-dominant rule. Do not edit this file after it has run.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { inflateSync } from 'node:zlib';

const REF = 'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-c1-zone-open.png';
const OTHERS = [
  'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-c2-zone-open.png',
  'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-c1-2154-open.png',
  'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-control-2154-open.png',
  'work/out/accept-k1-c1-zone-open.png',
  'work/out/accept-k1-c2-zone-open.png',
];

function readPng(file) {
  const data = readFileSync(file);
  const width = data.readUInt32BE(16);
  const height = data.readUInt32BE(20);
  const idat = [];
  for (let pos = 8; pos + 8 <= data.length;) {
    const length = data.readUInt32BE(pos);
    const kind = data.toString('latin1', pos + 4, pos + 8);
    if (kind === 'IDAT') idat.push(data.subarray(pos + 8, pos + 8 + length));
    pos += 12 + length;
    if (kind === 'IEND') break;
  }
  const raw = inflateSync(Buffer.concat(idat));
  const rows = [];
  const stride = width * 3;
  for (let y = 0; y < height; y++) {
    const filter = raw[(stride + 1) * y];
    if (filter !== 0) throw new Error('filter ' + filter + ' in ' + file);
    rows.push(raw.subarray((stride + 1) * y + 1, (stride + 1) * y + 1 + stride));
  }
  return { width, height, rows };
}

function px(row, x) {
  return [row[x * 3], row[x * 3 + 1], row[x * 3 + 2]];
}

function hexPix(p) {
  return p.map((v) => v.toString(16).padStart(2, '0')).join('');
}

function rowStat(img, y) {
  let nonblack = 0;
  let greenish = 0;
  let max = [0, 0, 0];
  for (let x = 0; x < img.width; x++) {
    const p = px(img.rows[y], x);
    if (p[0] > 24 || p[1] > 24 || p[2] > 24) nonblack += 1;
    if (p[1] > p[0] + 10 && p[1] > p[2] + 10 && p[1] > 24) greenish += 1;
    if (p[1] > max[1]) max = p;
  }
  const mid = Math.floor(img.width / 2);
  const center = [];
  for (let x = mid - 8; x <= mid + 8; x++) center.push(hexPix(px(img.rows[y], x)));
  return { y, nonblack, greenish, max: hexPix(max), center };
}

function iconBox(img, limitY) {
  let x0 = img.width;
  let y0 = limitY;
  let x1 = -1;
  let y1 = -1;
  let n = 0;
  for (let y = 0; y < limitY; y++) {
    for (let x = 0; x < img.width; x++) {
      const p = px(img.rows[y], x);
      if (p[0] < 16 && p[1] < 16 && p[2] < 16) continue;
      n += 1;
      if (x < x0) x0 = x;
      if (y < y0) y0 = y;
      if (x > x1) x1 = x;
      if (y > y1) y1 = y;
    }
  }
  if (!n) return null;
  return { x: x0, y: y0, w: x1 - x0 + 1, h: y1 - y0 + 1, pixels: n };
}

function hashRect(img, rect) {
  const parts = [];
  for (let y = rect.y; y < rect.y + rect.h; y++) {
    parts.push(img.rows[y].subarray(rect.x * 3, (rect.x + rect.w) * 3));
  }
  return createHash('sha256').update(Buffer.concat(parts)).digest('hex');
}

const ref = readPng(REF);
const stats = [];
for (let y = 0; y < Math.min(48, ref.height); y++) stats.push(rowStat(ref, y));
const rule = stats.reduce((best, row) => (row.greenish > best.greenish ? row : best), stats[0]);
const box = rule.greenish > 0 ? iconBox(ref, rule.y) : null;
const usable = box && box.w < 120 && box.h < 48 && box.pixels >= 8 && box.pixels < 4000;
const sha = usable ? hashRect(ref, box) : null;
const files = [];
for (const file of [REF, ...OTHERS]) {
  const img = readPng(file);
  const hash = usable && img.width === ref.width && img.height === ref.height ? hashRect(img, box) : null;
  files.push({ file, width: img.width, height: img.height, hash, match: hash === sha });
}
const doc = {
  width: ref.width,
  height: ref.height,
  topRows: stats,
  greenRule: { y: rule.y, greenish: rule.greenish, nonblack: rule.nonblack },
  rect: usable ? { x: box.x, y: box.y, w: box.w, h: box.h } : null,
  pixels: box ? box.pixels : 0,
  sha256: sha,
  usable,
  files,
  note: 'Pixel hash of the chooser header icon above the green rule. Not derived from help text.',
};
writeFileSync('work/out/header-ref-c2.json', JSON.stringify(doc, null, 2) + '\n');
console.log(JSON.stringify({
  width: ref.width,
  height: ref.height,
  greenRule: doc.greenRule,
  rect: doc.rect,
  pixels: doc.pixels,
  sha256: sha,
  usable,
  matches: files.map((f) => ({ file: f.file.split('/').pop(), match: f.match })),
  sample: stats.filter((row) => row.nonblack > 0 || row.greenish > 0).slice(0, 20),
}, null, 2));
